const upsertCategory = `-- name: UpsertCategory :exec
INSERT INTO categories (id, source_iri, scheme_id, name)
VALUES ($1, $2, $3, $4)
ON CONFLICT (source_iri) DO UPDATE SET scheme_id = excluded.scheme_id, name = excluded.name
`

type UpsertCategoryParams struct {
	ID        uuid.UUID
	SourceIri string
	SchemeID  uuid.UUID
	Name      string
}

func (q *Queries) UpsertCategory(ctx context.Context, arg UpsertCategoryParams) error {
	_, err := q.db.Exec(ctx, upsertCategory,
		arg.ID,
		arg.SourceIri,
		arg.SchemeID,
		arg.Name,
	)
	return err
}

